"""KPI catalog: single source for docs/kpi-definitions.md and dim_kpi_definition.

All targets are ILLUSTRATIVE demo targets, not BLS targets. Worked examples use toy numbers.
Reporting scope: month-granular date ranges (a range = whole calendar months). Reporting currency
conversion is applied to aggregated USD totals using the fixed rate table.
"""

FIELDS = ["kpi_id", "kpi_name", "domain", "tab", "definition", "formula", "numerator", "denominator",
          "source_fact", "grain", "date_field", "filters", "unit", "null_behavior", "target_direction",
          "illustrative_target", "worked_example", "dependencies"]


def K(kpi_id, name, domain, tab, definition, formula, source, grain, date_field, filters, unit, null_rule,
      direction, target, example, depends="-", num=None, den=None):
    return dict(zip(FIELDS, [kpi_id, name, domain, tab, definition, formula, num, den, source, grain, date_field,
                             filters, unit, null_rule, direction, target, example, depends]))


